import React, { useState } from 'react';
import {
  Alert,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Stack,
  TextField,
  Typography
} from '@mui/material';
import SendIcon from '@mui/icons-material/Send';
import api from '../../services/api';
import useAppTranslation from '../../hooks/useAppTranslation';

const SOURCE_LABELS: Record<string, string> = {
  llm: 'AI answer',
  regex: 'Platform insights',
  regex_fallback: 'Platform insights (AI unavailable)',
};

export default function CarbonCopilotPanel() {
  const { t } = useAppTranslation();
  const [message, setMessage] = useState('');
  const [answer, setAnswer] = useState('');
  const [answerSource, setAnswerSource] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const ask = async () => {
    if (!message.trim()) return;
    setLoading(true);
    setError('');
    try {
      const res = await api.askCarbonCopilot(message.trim());
      if (res.success) {
        const data = res.data as { answer?: string; source?: string; llmEnabled?: boolean };
        setAnswer(data?.answer || t('copilot.noAnswer'));
        setAnswerSource(data?.source || (data?.llmEnabled ? 'llm' : 'regex'));
      } else setError(res.message || t('copilot.questionFailed'));
    } catch (e) {
      setError(e instanceof Error ? e.message : t('copilot.questionFailed'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card variant="outlined">
      <CardContent>
        <Stack spacing={2}>
          <Typography variant="h6">{t('copilot.title')}</Typography>
          <Typography variant="body2" color="text.secondary">
            {t('copilot.subtitle')}
          </Typography>
          <TextField
            fullWidth
            multiline
            minRows={2}
            label={t('copilot.questionLabel')}
            placeholder={t('copilot.questionPlaceholder')}
            value={message}
            onChange={(e) => setMessage(e.target.value)}
          />
          <Button variant="contained" startIcon={loading ? <CircularProgress size={18} color="inherit" /> : <SendIcon />} onClick={ask} disabled={loading}>
            {t('copilot.ask')}
          </Button>
          {error && <Alert severity="error">{error}</Alert>}
          {answer && (
            <Alert severity="info">
              {answerSource ? (
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 0.5 }}>
                  {SOURCE_LABELS[answerSource] || answerSource}
                </Typography>
              ) : null}
              <Typography variant="body2">{answer}</Typography>
            </Alert>
          )}
        </Stack>
      </CardContent>
    </Card>
  );
}
